<script setup lang="ts">
// Day 2: Lines — Japan's Shinkansen lines from Overture Maps, glowing, with light pulses racing terminal to terminal
import ThreeView, { Color } from '@navaramap/three'
import { DefaultPlugin, type DefaultDescriptions } from '@navaramap/three-default-plugin'
import { LimbGlowMeshDesc, type LimbGlowConfig } from './lib/LimbGlowMeshDesc'
import { RailGlowMeshDesc, type RailGlowConfig } from './lib/RailGlowMeshDesc'
import { StarfieldMeshDesc, type StarfieldConfig } from './lib/StarfieldMeshDesc'

const baseURL = useRuntimeConfig().app.baseURL
// Generated by scripts/day02/extract_shinkansen.py; the land and coastline are Day 1's
const dataBase = `${baseURL}data/day02`
const day01Base = `${baseURL}data/day01`

const NAVY = '#060b1c'
const LAND = new Color().setStyle('#161d30')
const COAST = new Color().setStyle('#56628a')

type Routes = { features: { geometry: { coordinates: [number, number][] } }[] }

const container = ref<HTMLDivElement>()
let view: ThreeView<DefaultDescriptions> | undefined

onMounted(async () => {
  const v = new ThreeView<DefaultDescriptions>({
    container: container.value!,
    backgroundColor: new Color().setStyle(NAVY),
    animation: true,
  })
  view = v
  v.addPlugin(new DefaultPlugin())
  const [routes] = await Promise.all([
    fetch(`${dataBase}/shinkansen.geojson`).then((r) => r.json() as Promise<Routes>),
    v.init(),
  ])
  if (view !== v) return // unmounted while initializing
  v.registerMesh('limbGlow', LimbGlowMeshDesc)
  v.registerMesh('starfield', StarfieldMeshDesc)
  v.registerMesh('railGlow', RailGlowMeshDesc)

  v.globe.color = new Color().setStyle(NAVY)
  // Kagoshima to Hokkaido in one view, looking up the archipelago from the southwest
  v.setCamera({ lng: 135.6, lat: 33.6, height: 0, distance: 1_700_000, heading: 25, pitch: -50, roll: 0 })

  const bloom = v.addEffect({ selectiveBloom: { strength: 1.8, radius: 0.6, threshold: 0 } })

  // (typed separately: the view's mesh config union only knows the DefaultPlugin descriptors)
  const limbGlow: LimbGlowConfig = { limbGlow: { color: new Color().setStyle('#5b86ff'), intensity: 0.8, scaleHeight: 80_000 } }
  v.addMesh<LimbGlowMeshDesc>(limbGlow)
  const starfield: StarfieldConfig = { starfield: {} }
  v.addMesh<StarfieldMeshDesc>(starfield)

  // No basemap: a plain ellipsoid (the navy globe) for the clamped vectors to drape onto
  v.addLayer({ type: 'terrain', ellipsoid: {} })
  const land = v.addSource({ type: 'geojson', url: `${day01Base}/land.geojson` })
  v.addLayer({ type: 'vector', source: land, polygon: { color: LAND, clampToGround: true } })
  const coastline = v.addSource({ type: 'geojson', url: `${day01Base}/coastline.geojson` })
  v.addLayer({ type: 'vector', source: coastline, polyline: { color: COAST, width: 1, clampToGround: true } })

  // Shinkansen lines, each traced terminal to terminal
  const railGlow: RailGlowConfig = {
    effectIds: [bloom.id],
    railGlow: { routes: routes.features.map((f) => ({ coords: f.geometry.coordinates })) },
  }
  const rails = v.addMesh<RailGlowMeshDesc>(railGlow)
  v.on('preUpdate', () => rails.ref.tick(performance.now() / 1000))

  v.attribution?.add([
    {
      attributionHtml:
        '© <a href="https://overturemaps.org/">Overture Maps Foundation</a> · © <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
    },
  ])
})

onBeforeUnmount(() => {
  view?.dispose()
  view = undefined
})
</script>

<template>
  <div ref="container" class="map-canvas" />
</template>
